import pandas as pd
data = {'task': ['Task 1', 'Task 2'], 'status': ['pending', 'in_progress']}
df = pd.DataFrame(data)
for index, row in df.iterrows():
    if row['status'] == 'pending':
        print(f"Assigning {row['task']}")
    elif row['status'] == 'in_progress':
        print(f"{row['task']} is in progress")
